"""Statistics over the words of a text.

A word is a maximal run of characters for which ``str.isalnum()`` is true.
An apostrophe ``'`` that sits between two such characters is part of the
word (``don't``). Every other character separates words.
"""


def _words(text):
    """Return the words of ``text`` in order of appearance."""
    words = []
    i = 0
    n = len(text)
    while i < n:
        if not text[i].isalnum():
            i += 1
            continue
        start = i
        i += 1
        while i < n:
            ch = text[i]
            if ch.isalnum():
                i += 1
            elif ch == "'" and i + 1 < n and text[i + 1].isalnum():
                i += 2  # the apostrophe and the alphanumeric character after it
            else:
                break
        words.append(text[start:i])
    return words


def average_word_length(text):
    words = _words(text)
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def longest_word(text):
    best = ""
    for word in _words(text):
        if len(word) > len(best):
            best = word
    return best


def word_frequencies(text):
    counts = {}
    for word in _words(text):
        word = word.lower()
        counts[word] = counts.get(word, 0) + 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))
